-- =======================================================
-- ANALYTIC VIEWS
-- =======================================================

DROP VIEW IF EXISTS `vw_30day_readmissions`;
CREATE VIEW `vw_30day_readmissions` AS
SELECT
    fr.readmission_id,
    fr.index_admission_id,
    fr.readmit_admission_id,
    ia.patient_id,
    id_disch.`date`          AS index_discharge_date,
    ra_admit.`date`          AS readmit_admission_date,
    fr.days_to_readmit,
    fr.readmission_type,
    fr.readmission_reason_category,
    dp.age_group,
    dp.gender,
    dp.region,
    ins.payer_type,
    dd.department_name       AS index_department
FROM `fact_readmission` fr
JOIN `fact_admission`   ia        ON ia.admission_id      = fr.index_admission_id
JOIN `fact_admission`   ra        ON ra.admission_id      = fr.readmit_admission_id
JOIN `dim_date`         id_disch  ON id_disch.date_key    = ia.discharge_date_key
JOIN `dim_date`         ra_admit  ON ra_admit.date_key    = ra.admission_date_key
JOIN `dim_patient`      dp        ON dp.patient_id        = ia.patient_id
JOIN `dim_insurance`    ins       ON ins.insurance_id     = ia.insurance_id
JOIN `dim_department`   dd        ON dd.department_id     = ia.service_line_id;


DROP VIEW IF EXISTS `vw_admission_metrics`;
CREATE VIEW `vw_admission_metrics` AS
SELECT
    fa.admission_id,
    fa.patient_id,
    dp.age_group,
    dp.gender,
    dp.region,
    ins.insurance_name,
    ins.payer_type,
    dd.department_name,
    dg.diagnosis_group,
    dg.diagnosis_description    AS primary_diagnosis,
    adm_d.`date`                AS admission_date,
    adm_d.`year`                AS admission_year,
    adm_d.`month`               AS admission_month,
    adm_d.fiscal_period,
    dis_d.`date`                AS discharge_date,
    fa.length_of_stay,
    fa.severity_level,
    fa.comorbidity_count,
    fa.discharge_disposition,
    fa.medication_reconciliation_done,
    fa.follow_up_scheduled,
    fa.follow_up_days,
    fa.admission_source,
    CASE WHEN fr.readmission_id IS NOT NULL THEN 'Yes' ELSE 'No' END AS readmission_flag,
    fr.days_to_readmit,
    fr.readmission_type,
    fr.readmission_reason_category
FROM `fact_admission`   fa
JOIN `dim_patient`      dp    ON dp.patient_id        = fa.patient_id
JOIN `dim_insurance`    ins   ON ins.insurance_id      = fa.insurance_id
JOIN `dim_department`   dd    ON dd.department_id      = fa.service_line_id
JOIN `dim_diagnosis`    dg    ON dg.diagnosis_code     = fa.primary_diagnosis_code
JOIN `dim_date`         adm_d ON adm_d.date_key        = fa.admission_date_key
JOIN `dim_date`         dis_d ON dis_d.date_key        = fa.discharge_date_key
LEFT JOIN `fact_readmission` fr ON fr.index_admission_id = fa.admission_id;

SET FOREIGN_KEY_CHECKS=1;

